fn format_option(option: &OptionDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = option.abbr {
        text.push('-');
        text.push(abbr);
        text.push_str(", ");
    } else {
        text.push_str("    ");
    }
    text.push_str("--");
    if option.flag {
        text.push_str("(no-)");
    }
    text.push_str(&option.full);
    if let Some(choices) = &option.choices {
        text.push('=');
        let parts: Vec<String> = choices.iter().map(value_to_display).collect();
        text.push_str(&parts.join("|"));
    } else if let Some(metavar) = &option.metavar {
        text.push('=');
        text.push_str(metavar);
    }
    if option.list {
        text.push_str(" ...");
    }
    if option.default_help.is_some() || option.default.is_some() || option.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(help) = &option.help {
            text.push_str(help);
        }
        if option.default_help.is_some() || option.default.is_some() {
            if option.help.is_some() {
                text.push('\n');
            }
            text.push_str(&" ".repeat(text_length));
            text.push_str("(default: ");
            if let Some(default_help) = &option.default_help {
                text.push_str(default_help);
            } else if let Some(default) = &option.default {
                text.push_str(&value_to_display(default));
            }
            text.push(')');
        }
    }
    text
}

fn value_to_display(value: &Value) -> String {
    match value {
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        other => other.to_string(),
    }
}

pub fn get_help_text() -> String {
    let mut opts = cli_option_defs();
    opts.sort_by_key(|o| o.display_index);
    let rendered = opts.iter().map(format_option).collect::<Vec<_>>().join("\n");
    format!(
        r#"Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
"..." behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

{rendered}
"#
    )
}

fn throw_error(exit_code: i32, message: String, with_help: bool) -> ParseError {
    let message = if with_help {
        format!("{message}\n\n---\n\n{}", get_help_text())
    } else {
        message
    };
    ParseError { exit_code, message }
}

fn is_option(value: &str) -> bool {
    value.starts_with('-')
}

fn js_number(n: f64) -> Value {
    if n.is_finite() && n.fract() == 0.0 && n >= i64::MIN as f64 && n <= i64::MAX as f64 {
        json!(n as i64)
    } else if let Some(num) = Number::from_f64(n) {
        Value::Number(num)
    } else {
        Value::Null
    }
}

fn process_value(kind: ProcessKind, raw: &str) -> Result<Value, ParseError> {
    match kind {
        ProcessKind::Number => {
            let parsed = raw.trim().parse::<f64>().unwrap_or(f64::NAN);
            Ok(js_number(parsed))
        }
        ProcessKind::ParserConfig => {
            let bytes = fs::read(raw).map_err(|err| ParseError {
                exit_code: 1,
                message: format!("ENOENT: no such file or directory, open '{raw}'")
                    .replace("ENOENT", classify_io_error(&err, raw).0)
                    .replace(
                        "no such file or directory, open",
                        classify_io_error(&err, raw).1,
                    ),
            });
            let bytes = match fs::read(raw) {
                Ok(b) => b,
                Err(err) => {
                    return Err(ParseError {
                        exit_code: 1,
                        message: format_node_fs_error(&err, raw),
                    });
                }
            };
            match serde_json::from_slice::<Value>(&bytes) {
                Ok(v) => Ok(v),
                Err(err) => Err(ParseError {
                    exit_code: 1,
                    message: format_json_error(&err, raw, &bytes),
                }),
            }
        }
    }
}

fn classify_io_error<'a>(err: &'a std::io::Error, _path: &str) -> (&'a str, &'a str) {
    match err.kind() {
        std::io::ErrorKind::NotFound => ("ENOENT", "no such file or directory, open"),
        std::io::ErrorKind::PermissionDenied => ("EACCES", "permission denied, open"),
        _ => ("EIO", "i/o error, open"),
    }
}

fn format_node_fs_error(err: &std::io::Error, path: &str) -> String {
    match err.kind() {
        std::io::ErrorKind::NotFound => {
            format!("ENOENT: no such file or directory, open '{path}'")
        }
        std::io::ErrorKind::PermissionDenied => {
            format!("EACCES: permission denied, open '{path}'")
        }
        _ => format!("{err}")
    }
}

fn format_json_error(err: &serde_json::Error, path: &str, bytes: &[u8]) -> String {
    // Node's JSON.parse error messages. Try to stay close enough for tests.
    let text = String::from_utf8_lossy(bytes);
    if text.trim().is_empty() {
        return "Unexpected end of JSON input".into();
    }
    let _ = path;
    format!("Unexpected token in JSON: {err}")
}

fn try_json_parse(value: &str) -> Value {
    match serde_json::from_str::<Value>(value) {
        Ok(v) => v,
        Err(_) => Value::String(value.to_string()),
    }
}

fn strip_option_prefix(name: &str) -> String {
    let mut rest = name;
    if let Some(stripped) = rest.strip_prefix("--") {
        rest = stripped;
    } else if let Some(stripped) = rest.strip_prefix('-') {
        rest = stripped;
    }
    rest.strip_prefix("no-").unwrap_or(rest).to_string()
}

struct Prepared {
    defs: Vec<OptionDef>,
    by_flag: HashMap<String, usize>,
}

fn prepare_options() -> Prepared {
    let defs = cli_option_defs();
    let mut by_flag = HashMap::new();
    for (idx, option) in defs.iter().enumerate() {
        by_flag.insert(format!("--{}", option.full), idx);
        if let Some(abbr) = option.abbr {
            by_flag.insert(format!("-{abbr}"), idx);
        }
        if option.flag {
            by_flag.insert(format!("--no-{}", option.full), idx);
        }
    }
    Prepared { defs, by_flag }
}

pub fn parse_args(args: &[String]) -> Result<ParsedArgs, ParseError> {
    let prepared = prepare_options();
    let mut parsed_options: Map<String, Value> = Map::new();
    let mut positional_arguments = Vec::new();

    for option in &prepared.defs {
        if let Some(default) = &option.default {
            parsed_options.insert(option.key.clone(), default.clone());
        } else if option.list {
            parsed_options.insert(option.key.clone(), Value::Array(vec![]));
        }
    }

    // Sentinel used only internally; never exposed.
    const MISSING: &str = "__js_missing_value__";

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            if let Some(index) = arg.find('=') {
                option_name = arg[..index].to_string();
                value = Some(arg[index + 1..].to_string());
            }

            let mut unknown: Option<OptionDef> = None;
            let known_idx = prepared.by_flag.get(&option_name).copied();
            let option: OptionDef = if let Some(idx) = known_idx {
                prepared.defs[idx].clone()
            } else {
                let real_option_name = strip_option_prefix(&option_name);
                let existing = parsed_options.get(&real_option_name);
                let is_list = existing.map(|v| v != &Value::Bool(true)).unwrap_or(false);
                let next_is_option = args.get(i + 1).map(|s| is_option(s)).unwrap_or(true);
                let flag = existing.is_none() && value.is_none() && next_is_option;
                if is_list {
                    if let Some(current) = parsed_options.get(&real_option_name).cloned() {
                        if !current.is_array() {
                            parsed_options.insert(
                                real_option_name.clone(),
                                if current == Value::Bool(true) {
                                    Value::Array(vec![])
                                } else {
                                    Value::Array(vec![current])
                                },
                            );
                        }
                    }
                }
                let def = OptionDef {
                    key: real_option_name.clone(),
                    full: real_option_name,
                    abbr: None,
                    flag,
                    list: is_list,
                    default: None,
                    default_help: None,
                    choices: None,
                    help: None,
                    metavar: None,
                    display_index: 0,
                    callback: None,
                    process: None,
                };
                unknown = Some(def.clone());
                def
            };
            let _ = unknown;

            if let Some(callback) = option.callback {
                let message = match callback {
                    CallbackKind::Help => get_help_text(),
                    CallbackKind::Version => crate::package::version_text(),
                };
                return Err(throw_error(0, message, false));
            } else if option.flag {
                let assigned = if option_name.starts_with("--no-") {
                    json!(false)
                } else if let Some(v) = &value {
                    json!(v == "1")
                } else {
                    json!(true)
                };
                parsed_options.insert(option.key, assigned);
            } else {
                if value.is_none() && i < args.len() - 1 && !is_option(&args[i + 1]) {
                    value = Some(args[i + 1].clone());
                    i += 1;
                }
                if let Some(raw) = value {
                    let processed = if let Some(kind) = option.process {
                        process_value(kind, &raw)?
                    } else if known_idx.is_none() {
                        try_json_parse(&raw)
                    } else {
                        Value::String(raw)
                    };
                    if option.list {
                        parsed_options
                            .entry(option.key)
                            .or_insert_with(|| Value::Array(vec![]));
                        if let Some(Value::Array(arr)) = parsed_options.get_mut(&option.key) {
                            arr.push(processed);
                        }
                    } else {
                        parsed_options.insert(option.key, processed);
                    }
                } else {
                    parsed_options.insert(option.key, Value::String(MISSING.into()));
                }
            }
        } else if regex_is_digits(arg) {
            let n: i64 = arg.parse().unwrap_or(0);
            positional_arguments.push(json!(n));
        } else {
            positional_arguments.push(Value::String(arg.clone()));
        }
        i += 1;
    }

    for (name, value) in &parsed_options {
        if value.as_str() == Some(MISSING) {
            let full = prepared
                .defs
                .iter()
                .find(|d| &d.key == name)
                .map(|d| d.full.clone())
                .unwrap_or_else(|| name.clone());
            return Err(throw_error(
                1,
                format!("Missing value: --{full} requires a value"),
                true,
            ));
        }
    }

    validate_options(&parsed_options, &prepared.defs)?;

    Ok(ParsedArgs {
        positional_arguments,
        options: parsed_options,
    })
}

fn regex_is_digits(arg: &str) -> bool {
    !arg.is_empty() && arg.bytes().all(|b| b.is_ascii_digit())
}

fn validate_options(
    parsed_options: &Map<String, Value>,
    defs: &[OptionDef],
) -> Result<(), ParseError> {
    let mut errors = Vec::new();
    for option in defs {
        if let Some(choices) = &option.choices {
            if let Some(value) = parsed_options.get(&option.key) {
                if !choices.iter().any(|c| json_eq(c, value)) {
                    let joined = choices
                        .iter()
                        .map(value_to_display)
                        .collect::<Vec<_>>()
                        .join(",");
                    errors.push(format!(
                        "Error: --{} must be one of the values {joined}",
                        option.full
                    ));
                }
            }
        }
    }
    if !errors.is_empty() {
        return Err(throw_error(1, errors.join("\n"), true));
    }
    Ok(())
}

fn json_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        _ => a == b,
    }
}

pub fn parse_cli(args: &[String]) -> Result<ParsedArgs, ParseError> {
    parse_args(args)
}

pub fn paths_from_positionals(positionals: &[Value]) -> Vec<String> {
    positionals
        .iter()
        .map(|v| match v {
            Value::String(s) => s.clone(),
            other => value_to_display(other),
        })
        .collect()
}

pub fn option_bool(options: &Map<String, Value>, key: &str) -> bool {
    match options.get(key) {
        Some(Value::Bool(b)) => *b,
        Some(Value::Number(n)) => n.as_f64().unwrap_or(0.0) != 0.0,
        Some(Value::String(s)) => !s.is_empty() && s != "false" && s != "0",
        Some(Value::Null) | None => false,
        Some(_) => true,
    }
}

pub fn option_u32(options: &Map<String, Value>, key: &str) -> Option<u32> {
    match options.get(key) {
        Some(Value::Number(n)) => n.as_f64().map(|f| f as u32),
        Some(Value::String(s)) => s.parse().ok(),
        _ => None,
    }
}

pub fn option_string(options: &Map<String, Value>, key: &str) -> Option<String> {
    match options.get(key) {
        Some(Value::String(s)) => Some(s.clone()),
        Some(Value::Number(n)) => Some(n.to_string()),
        Some(Value::Bool(b)) => Some(b.to_string()),
        _ => None,
    }
}

pub fn option_string_list(options: &Map<String, Value>, key: &str) -> Vec<String> {
    match options.get(key) {
        Some(Value::Array(arr)) => arr
            .iter()
            .filter_map(|v| match v {
                Value::String(s) => Some(s.clone()),
                Value::Number(n) => Some(n.to_string()),
                _ => None,
            })
            .collect(),
        Some(Value::String(s)) => vec![s.clone()],
        _ => Vec::new(),
    }
}

pub fn resolve_transform_path(transform: &str) -> String {
    if transform.starts_with("http://") || transform.starts_with("https://") {
        transform.to_string()
    } else {
        std::env::current_dir()
            .map(|cwd| cwd.join(transform))
            .unwrap_or_else(|_| Path::new(transform).to_path_buf())
            .to_string_lossy()
            .into_owned()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn help_contains_core_usage() {
        let help = get_help_text();
        assert!(help.starts_with("Usage: jscodeshift [OPTION]... PATH..."));
        assert!(help.contains("      --(no-)babel              apply babeljs to the transform file"));
        assert!(help.contains("  -c, --cpus=N                  start at most N child processes to process source files"));
        assert!(help.contains("      --(no-)fail-on-error      Return a non-zero code when there are errors"));
        assert!(help.contains("      --parser=babel|babylon|flow|ts|tsx  the parser to use for parsing the source files"));
        assert!(help.contains("  -v, --verbose=0|1|2           show more information about the transform process"));
        assert!(help.contains("(default: cjs,es,es6,js,jsx,mjs,ts,tsx)"));
    }
}
