{"path":"/workspace/src/colors.rs","command":"create","file_text":"//! picocolors-compatible terminal coloring.

use std::env;
use std::io::{stdout, IsTerminal};

pub struct Colors {
    enabled: bool,
}

impl Colors {
    pub fn detect(argv: &[String]) -> Self {
        let no_color = env::var_os("NO_COLOR").is_some() || argv.iter().any(|a| a == "--no-color");
        let force = env::var_os("FORCE_COLOR").is_some()
            || argv.iter().any(|a| a == "--color")
            || env::consts::OS == "windows"
            || (stdout().is_terminal() && env::var("TERM").ok().as_deref() != Some("dumb"))
            || env::var_os("CI").is_some();
        Self {
            enabled: !no_color && force,
        }
    }

    pub fn is_enabled(&self) -> bool {
        self.enabled
    }

    fn wrap(&self, open: &str, close: &str, input: &str) -> String {
        if !self.enabled {
            return input.to_string();
        }
        format!("{open}{input}{close}")
    }

    pub fn white(&self, input: &str) -> String {
        self.wrap("\x1b[37m", "\x1b[39m", input)
    }

    pub fn red(&self, input: &str) -> String {
        self.wrap("\x1b[31m", "\x1b[39m", input)
    }

    pub fn green(&self, input: &str) -> String {
        self.wrap("\x1b[32m", "\x1b[39m", input)
    }

    pub fn yellow(&self, input: &str) -> String {
        self.wrap("\x1b[33m", "\x1b[39m", input)
    }

    pub fn blue(&self, input: &str) -> String {
        self.wrap("\x1b[34m", "\x1b[39m", input)
    }

    pub fn bg_red(&self, input: &str) -> String {
        self.wrap("\x1b[41m", "\x1b[49m", input)
    }

    pub fn bg_green(&self, input: &str) -> String {
        self.wrap("\x1b[42m", "\x1b[49m", input)
    }

    pub fn bg_yellow(&self, input: &str) -> String {
        self.wrap("\x1b[43m", "\x1b[49m", input)
    }

    pub fn bg_blue(&self, input: &str) -> String {
        self.wrap("\x1b[44m", "\x1b[49m", input)
    }

    pub fn banner_ok(&self) -> String {
        self.bg_green(&self.white(" OKK "))
    }

    pub fn banner_nochange(&self) -> String {
        self.bg_yellow(&self.white(" NOC "))
    }

    pub fn banner_skip(&self) -> String {
        self.bg_yellow(&self.white(" SKIP "))
    }

    pub fn banner_error(&self) -> String {
        self.bg_red(&self.white(" ERR "))
    }

    pub fn banner_report(&self) -> String {
        self.bg_blue(&self.white(" REP "))
    }

    pub fn banner_fatal(&self) -> String {
        self.bg_red(&self.white("ERROR"))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn disabled_is_identity() {
        let c = Colors { enabled: false };
        assert_eq!(c.green("ok"), "ok");
        assert_eq!(c.banner_ok(), " OKK ");
    }

    #[test]
    fn enabled_wraps() {
        let c = Colors { enabled: true };
        assert_eq!(c.white("X"), "\x1b[37mX\x1b[39m");
        assert_eq!(c.bg_green("X"), "\x1b[42mX\x1b[49m");
    }
}
"}

{"path":"/workspace/src/utils.rs","command":"create","file_text":"//! Shared path and string helpers matching Node.js semantics.

use std::env;
use std::path::{Component, Path, PathBuf};

pub fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{s}\n")
    }
}

/// Node's `path.extname`.
pub fn node_extname(path: &str) -> String {
    let base = match path.rsplit_once(['/', '\\']) {
        Some((_, rest)) => rest,
        None => path,
    };
    if base.is_empty() || base == "." || base == ".." {
        return String::new();
    }
    match base.rfind('.') {
        Some(0) | None => String::new(),
        Some(i) => base[i..].to_string(),
    }
}

/// Normalize `.` / `..` without requiring the path to exist.
pub fn normalize_path(path: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in path.components() {
        match c {
            Component::CurDir => {}
            Component::ParentDir => {
                if !out.pop() {
                    out.push("..");
                }
            }
            other => out.push(other.as_os_str()),
        }
    }
    if out.as_os_str().is_empty() {
        PathBuf::from(".")
    } else {
        out
    }
}

/// Node `path.resolve` for a single path argument.
pub fn path_resolve(p: &str) -> PathBuf {
    if p.starts_with("http://") || p.starts_with("https://") {
        return PathBuf::from(p);
    }
    let path = Path::new(p);
    let joined = if path.is_absolute() {
        path.to_path_buf()
    } else {
        env::current_dir()
            .map(|cwd| cwd.join(path))
            .unwrap_or_else(|_| path.to_path_buf())
    };
    normalize_path(&joined)
}

/// Strip a leading `./` / `../` traversal prefix, matching ignoreFiles.js.
pub fn strip_leading_traversal(path: &str) -> String {
    let re = regex::Regex::new(r"^(?:\.\.?[/\\])+").unwrap();
    re.replace(path, "").into_owned()
}

pub fn available_cpus() -> usize {
    match std::thread::available_parallelism() {
        Ok(n) => n.get().saturating_sub(1).max(1),
        Err(_) => 1,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn extname_matches_node() {
        assert_eq!(node_extname("foo.js"), ".js");
        assert_eq!(node_extname("foo.d.ts"), ".ts");
        assert_eq!(node_extname(".gitignore"), "");
        assert_eq!(node_extname("foo"), "");
        assert_eq!(node_extname("dir/foo.JS"), ".JS");
        assert_eq!(node_extname("http://x.com/a.js?q=1"), ".js?q=1");
    }

    #[test]
    fn line_break_appends_once() {
        assert_eq!(line_break("a"), "a\n");
        assert_eq!(line_break("a\n"), "a\n");
    }

    #[test]
    fn strip_traversal() {
        assert_eq!(strip_leading_traversal("../../foo"), "foo");
        assert_eq!(strip_leading_traversal("././bar"), "bar");
        assert_eq!(strip_leading_traversal("foo/bar"), "foo/bar");
    }
}
"}

{"path":"/workspace/src/package.rs","command":"create","file_text":"//! Package utilities: locate the JS package root and emit `--version` text.

use serde_json::Value;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};

const JSCODESHIFT_VERSION: &str = env!("CARGO_PKG_VERSION");

pub fn version_text() -> String {
    let root = find_package_root();
    let babel = package_version(&root, "@babel/core")
        .or_else(|| field_version(&root, "@babel/core", "version"))
        .unwrap_or_default();
    let babylon = require_package(&root, "@babel/parser")
        .and_then(|pkg| pkg_field(&pkg, "version"))
        .unwrap_or_default();
    let flow = require_package(&root, "flow-parser")
        .and_then(|pkg| pkg_field(&pkg, "version"))
        .unwrap_or_default();
    let recast = require_package(&root, "recast")
        .and_then(|pkg| pkg_field(&pkg, "version"))
        .unwrap_or_default();

    format!(
        "jscodeshift: {JSCODESHIFT_VERSION}\n - babel: {babel}\n - babylon: {babylon}\n - flow: {flow}\n - recast: {recast}\n"
    )
}

pub fn find_package_root() -> PathBuf {
    if let Ok(root) = env::var("JSCODESHIFT_ROOT") {
        let p = PathBuf::from(root);
        if p.join("package.json").is_file() || p.join("src/Worker.js").is_file() {
            return p;
        }
    }

    let mut candidates = Vec::new();
    if let Ok(exe) = env::current_exe() {
        if let Some(dir) = exe.parent() {
            for rel in [
                ".",
                "..",
                "../codebase",
                "../../codebase",
                "../../../codebase",
                "../..",
            ] {
                candidates.push(dir.join(rel));
            }
        }
    }
    if let Ok(cwd) = env::current_dir() {
        let mut dir = cwd;
        for _ in 0..8 {
            candidates.push(dir.join("codebase"));
            candidates.push(dir.clone());
            if !dir.pop() {
                break;
            }
        }
    }
    candidates.push(PathBuf::from("/workspace/codebase"));
    candidates.push(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("codebase"));

    for c in candidates {
        let normalized = crate::utils::normalize_path(&c);
        if is_jscodeshift_root(&normalized) {
            return normalized;
        }
    }
    PathBuf::from("/workspace/codebase")
}

fn is_jscodeshift_root(path: &Path) -> bool {
    let pkg = path.join("package.json");
    if !pkg.is_file() {
        return path.join("src/Worker.js").is_file();
    }
    if let Ok(bytes) = fs::read(&pkg) {
        if let Ok(v) = serde_json::from_slice::<Value>(&bytes) {
            if v.get("name").and_then(|n| n.as_str()) == Some("jscodeshift") {
                return true;
            }
        }
    }
    path.join("src/Worker.js").is_file()
}

pub fn find_bridge_script() -> PathBuf {
    if let Ok(p) = env::var("JSCODESHIFT_BRIDGE") {
        let pb = PathBuf::from(p);
        if pb.is_file() {
            return pb;
        }
    }
    let root = find_package_root();
    let in_pkg = root.join("bridge/transform-host.js");
    if in_pkg.is_file() {
        return in_pkg;
    }
    let workspace = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("bridge/transform-host.js");
    if workspace.is_file() {
        return workspace;
    }
    PathBuf::from("/workspace/bridge/transform-host.js")
}

fn read_json(path: &Path) -> Option<Value> {
    serde_json::from_slice(&fs::read(path).ok()?).ok()
}

fn pkg_field(pkg: &Value, field: &str) -> Option<String> {
    pkg.get(field)?.as_str().map(|s| s.to_string())
}

fn package_version(root: &Path, name: &str) -> Option<String> {
    require_package(root, name).and_then(|pkg| pkg_field(&pkg, "version"))
}

fn field_version(root: &Path, name: &str, field: &str) -> Option<String> {
    require_package(root, name).and_then(|pkg| pkg_field(&pkg, field))
}

/// Walk from `require.resolve(name)` looking for a matching package.json,
/// matching `utils/requirePackage.js`.
pub fn require_package(root: &Path, name: &str) -> Option<Value> {
    let mut search_roots = vec![root.to_path_buf()];
    if let Some(parent) = root.parent() {
        search_roots.push(parent.to_path_buf());
    }
    if let Ok(cwd) = env::current_dir() {
        search_roots.push(cwd);
    }

    for base in search_roots {
        let mut dir = base.join("node_modules").join(name);
        if !dir.is_dir() {
            continue;
        }
        // Prefer the package root itself, then walk up like requirePackage.
        let start = if dir.join("package.json").is_file() {
            dir.clone()
        } else {
            dir.clone()
        };
        let mut cur = start;
        loop {
            let pkg_path = cur.join("package.json");
            if let Some(pkg) = read_json(&pkg_path) {
                if pkg.get("name").and_then(|n| n.as_str()) == Some(name) {
                    return Some(pkg);
                }
            }
            if !cur.pop() {
                break;
            }
            if cur.as_os_str() == "/" {
                break;
            }
        }
        // Fallback: node_modules/<name>/package.json even if name mismatches.
        if let Some(pkg) = read_json(&dir.join("package.json")) {
            return Some(pkg);
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn version_text_contains_jscodeshift() {
        let text = version_text();
        assert!(text.starts_with("jscodeshift: 17.4.0\n"));
        assert!(text.contains(" - babel: "));
        assert!(text.contains(" - recast: "));
        assert!(text.ends_with('\n'));
    }
}
"}

{"path":"/workspace/src/ignore.rs","command":"create","file_text":"//! Ignore-pattern handling matching `src/ignoreFiles.js` + picomatch `{dot:true}`.

use crate::utils::strip_leading_traversal;
use regex::Regex;
use std::fs;
use std::io;
use std::path::Path;

#[derive(Default)]
pub struct IgnoreSet {
    matchers: Vec<CompiledGlob>,
}

struct CompiledGlob {
    source: String,
    regex: Regex,
}

impl IgnoreSet {
    pub fn new() -> Self {
        Self {
            matchers: Vec::new(),
        }
    }

    pub fn add(&mut self, input: impl IntoIgnoreInput) {
        for pattern in input.into_patterns() {
            self.add_ignore_pattern(&pattern);
        }
    }

    pub fn add_from_file(&mut self, input: impl IntoIgnoreInput) -> io::Result<()> {
        for config in input.into_patterns() {
            let stats = fs::metadata(&config)?;
            if stats.is_file() {
                let content = fs::read_to_string(&config)?;
                for line in content.split('\n') {
                    let line = line.strip_suffix('\r').unwrap_or(line);
                    self.add_ignore_pattern(line);
                }
            }
        }
        Ok(())
    }

    fn add_ignore_pattern(&mut self, val: &str) {
        if val.is_empty() || val.as_bytes().first() == Some(&b'#') {
            return;
        }
        let pattern = val.to_string();
        if !pattern.contains('/') {
            self.push_matcher(&format!("**/{pattern}"));
        } else if pattern.ends_with('/') {
            self.push_matcher(&format!("**/{pattern}**"));
            self.push_matcher(&format!("{pattern}**"));
        }
        self.push_matcher(&pattern);
    }

    fn push_matcher(&mut self, pattern: &str) {
        for expanded in expand_braces(pattern) {
            if let Some(regex) = glob_to_regex(&expanded) {
                self.matchers.push(CompiledGlob {
                    source: expanded,
                    regex,
                });
            }
        }
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        if self.is_match(path) {
            return true;
        }
        let normalized = strip_leading_traversal(path);
        normalized != path && self.is_match(&normalized)
    }

    fn is_match(&self, path: &str) -> bool {
        self.matchers.iter().any(|m| m.regex.is_match(path))
    }

    pub fn is_empty(&self) -> bool {
        self.matchers.is_empty()
    }
}

pub trait IntoIgnoreInput {
    fn into_patterns(self) -> Vec<String>;
}

impl IntoIgnoreInput for Vec<String> {
    fn into_patterns(self) -> Vec<String> {
        self
    }
}

impl IntoIgnoreInput for &[String] {
    fn into_patterns(self) -> Vec<String> {
        self.to_vec()
    }
}

impl IntoIgnoreInput for &str {
    fn into_patterns(self) -> Vec<String> {
        vec![self.to_string()]
    }
}

impl IntoIgnoreInput for String {
    fn into_patterns(self) -> Vec<String> {
        vec![self]
    }
}

impl IntoIgnoreInput for Option<String> {
    fn into_patterns(self) -> Vec<String> {
        self.into_iter().collect()
    }
}

/// Expand `{a,b}` style braces. Unbalanced braces are left as-is.
fn expand_braces(pattern: &str) -> Vec<String> {
    let chars: Vec<char> = pattern.chars().collect();
    if let Some((pre, inner, post)) = find_first_brace(&chars) {
        let mut out = Vec::new();
        for alt in split_top_level_commas(&inner) {
            let combined = format!("{pre}{alt}{post}");
            out.extend(expand_braces(&combined));
        }
        if out.is_empty() {
            vec![pattern.to_string()]
        } else {
            out
        }
    } else {
        vec![pattern.to_string()]
    }
}

fn find_first_brace(chars: &[char]) -> Option<(String, String, String)> {
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\\' {
            i += 2;
            continue;
        }
        if chars[i] == '{' {
            let mut depth = 1;
            let mut j = i + 1;
            while j < chars.len() {
                if chars[j] == '\\' {
                    j += 2;
                    continue;
                }
                if chars[j] == '{' {
                    depth += 1;
                } else if chars[j] == '}' {
                    depth -= 1;
                    if depth == 0 {
                        let pre: String = chars[..i].iter().collect();
                        let inner: String = chars[i + 1..j].iter().collect();
                        let post: String = chars[j + 1..].iter().collect();
                        if inner.contains(',') || inner.is_empty() {
                            return Some((pre, inner, post));
                        }
                        break;
                    }
                }
                j += 1;
            }
        }
        i += 1;
    }
    None
}

fn split_top_level_commas(inner: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut cur = String::new();
    let mut depth = 0;
    let chars: Vec<char> = inner.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' {
            cur.push(c);
            if i + 1 < chars.len() {
                cur.push(chars[i + 1]);
                i += 2;
                continue;
            }
        } else if c == '{' {
            depth += 1;
            cur.push(c);
        } else if c == '}' {
            depth -= 1;
            cur.push(c);
        } else if c == ',' && depth == 0 {
            parts.push(std::mem::take(&mut cur));
        } else {
            cur.push(c);
        }
        i += 1;
    }
    parts.push(cur);
    parts
}

fn glob_to_regex(pattern: &str) -> Option<Regex> {
    let mut re = String::from("^");
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        match chars[i] {
            '\\' => {
                if i + 1 < chars.len() {
                    re.push_str(&regex::escape(&chars[i + 1].to_string()));
                    i += 2;
                } else {
                    re.push_str("\\\\");
                    i += 1;
                }
            }
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    let after = i + 2;
                    let before_slash = i == 0 || chars[i - 1] == '/';
                    if after < chars.len() && chars[after] == '/' && (before_slash || i == 0) {
                        // `**/` matches zero or more directories
                        re.push_str("(?:.*/)?");
                        i += 3;
                    } else {
                        re.push_str(".*");
                        i += 2;
                    }
                } else {
                    re.push_str("[^/]*");
                    i += 1;
                }
            }
            '?' => {
                re.push_str("[^/]");
                i += 1;
            }
            '[' => {
                if let Some((cls, next)) = take_class(&chars, i) {
                    re.push_str(&cls);
                    i = next;
                } else {
                    re.push_str("\\[");
                    i += 1;
                }
            }
            c => {
                re.push_str(&regex::escape(&c.to_string()));
                i += 1;
            }
        }
    }
    re.push('$');
    Regex::new(&re).ok()
}

fn take_class(chars: &[char], start: usize) -> Option<(String, usize)> {
    // start points at '['
    if start + 1 >= chars.len() {
        return None;
    }
    let mut i = start + 1;
    let mut out = String::from("[");
    if chars[i] == '!' || chars[i] == '^' {
        out.push('^');
        i += 1;
    }
    if i < chars.len() && chars[i] == ']' {
        out.push(']');
        i += 1;
    }
    while i < chars.len() {
        if chars[i] == ']' {
            out.push(']');
            return Some((out, i + 1));
        }
        if chars[i] == '\\' && i + 1 < chars.len() {
            out.push('\\');
            out.push(chars[i + 1]);
            i += 2;
            continue;
        }
        out.push(chars[i]);
        i += 1;
    }
    None
}

/// Convenience: load ignore files used by the runner.
pub fn load_for_run(
    ignore_set: &[String],
    ignore_pattern: &[String],
    ignore_config: &[String],
    gitignore: bool,
) -> io::Result<IgnoreSet> {
    let mut set = IgnoreSet::new();
    set.add(ignore_set);
    set.add(ignore_pattern);
    if !ignore_config.is_empty() {
        set.add_from_file(ignore_config)?;
    }
    if gitignore {
        let path = std::env::current_dir()
            .unwrap_or_else(|_| Path::new(".").to_path_buf())
            .join(".gitignore");
        set.add_from_file(path.to_string_lossy().as_ref())?;
    }
    Ok(set)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bare_name_matches_nested() {
        let mut s = IgnoreSet::new();
        s.add("node_modules");
        assert!(s.should_ignore("src/node_modules"));
        assert!(s.should_ignore("node_modules"));
        assert!(s.should_ignore("src/node_modules/foo.js"));
        assert!(!s.should_ignore("src/not_node_modules"));
    }

    #[test]
    fn directory_slash_pattern() {
        let mut s = IgnoreSet::new();
        s.add("dist/");
        assert!(s.should_ignore("dist/index.js"));
        assert!(s.should_ignore("pkg/dist/index.js"));
    }

    #[test]
    fn glob_star() {
        let mut s = IgnoreSet::new();
        s.add("*.log");
        assert!(s.should_ignore("foo.log"));
        assert!(s.should_ignore("dir/foo.log"));
        assert!(!s.should_ignore("foo.txt"));
    }

    #[test]
    fn strips_traversal_prefix() {
        let mut s = IgnoreSet::new();
        s.add("node_modules");
        assert!(s.should_ignore("../src/node_modules/a.js"));
        assert!(s.should_ignore("./node_modules"));
    }

    #[test]
    fn comments_and_empty_ignored() {
        let mut s = IgnoreSet::new();
        s.add("# comment");
        s.add("");
        assert!(s.is_empty());
    }

    #[test]
    fn braces() {
        let mut s = IgnoreSet::new();
        s.add("*.{js,ts}");
        assert!(s.should_ignore("a.js"));
        assert!(s.should_ignore("a.ts"));
        assert!(!s.should_ignore("a.rs"));
    }
}
"}

{"path":"/workspace/src/worker.rs","command":"create","file_text":"//! Worker: spawn the Node.js transform-host for one file.

use crate::colors::Colors;
use crate::package::find_bridge_script;
use crate::utils::line_break;
use serde::{Deserialize, Serialize};
use serde_json::{json, Map, Value};
use std::io::{Read, Write};
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::sync::OnceLock;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum FileStatus {
    Ok,
    Nochange,
    Skip,
    Error,
}

impl FileStatus {
    pub fn as_str(self) -> &'static str {
        match self {
            FileStatus::Ok => "ok",
            FileStatus::Nochange => "nochange",
            FileStatus::Skip => "skip",
            FileStatus::Error => "error",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FileResult {
    pub path: String,
    pub status: FileStatus,
    #[serde(default)]
    pub msg: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Stats {
    pub time_elapsed: f64,
    pub stats: Map<String, Value>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "action")]
pub enum WorkerEvent {
    #[serde(rename = "status")]
    Status(FileResult),
    #[serde(rename = "free")]
    Free,
    #[serde(rename = "report")]
    Report { msg: String },
    #[serde(rename = "update")]
    Update { msg: String },
}

static NODE_BIN: OnceLock<PathBuf> = OnceLock::new();

pub fn node_binary() -> PathBuf {
    NODE_BIN
        .get_or_init(|| {
            if let Ok(p) = std::env::var("JSCODESHIFT_NODE") {
                return PathBuf::from(p);
            }
            which("node").unwrap_or_else(|| PathBuf::from("node"))
        })
        .clone()
}

fn which(name: &str) -> Option<PathBuf> {
    let path = std::env::var_os("PATH")?;
    for dir in std::env::split_paths(&path) {
        let candidate = dir.join(name);
        if candidate.is_file() {
            return Some(candidate);
        }
        #[cfg(windows)]
        {
            let exe = dir.join(format!("{name}.exe"));
            if exe.is_file() {
                return Some(exe);
            }
        }
    }
    None
}

pub fn run_file(
    file: &str,
    options: &Map<String, Value>,
    transform_file: &str,
    colors: &Colors,
) -> (FileResult, Option<String>, Option<String>) {
    let bridge = find_bridge_script();
    let payload = json!({
        "file": file,
        "transformFile": transform_file,
        "options": options,
    });

    let mut child = match Command::new(node_binary())
        .arg(&bridge)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
    {
        Ok(c) => c,
        Err(err) => {
            return (
                FileResult {
                    path: file.to_string(),
                    status: FileStatus::Error,
                    msg: format!("{file} {err}\n"),
                },
                None,
                None,
            );
        }
    };

    if let Some(mut stdin) = child.stdin.take() {
        let _ = writeln!(stdin, "{payload}");
    }

    let mut stdout = String::new();
    if let Some(mut out) = child.stdout.take() {
        let _ = out.read_to_string(&mut stdout);
    }
    let mut stderr = String::new();
    if let Some(mut err) = child.stderr.take() {
        let _ = err.read_to_string(&mut stderr);
    }
    let _ = child.wait();

    parse_worker_output(file, &stdout, &stderr, colors)
}

fn parse_worker_output(
    file: &str,
    stdout: &str,
    stderr: &str,
    colors: &Colors,
) -> (FileResult, Option<String>, Option<String>) {
    let mut last_status: Option<FileResult> = None;
    let mut report: Option<String> = None;
    let mut update: Option<String> = None;

    for line in stdout.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        match serde_json::from_str::<Value>(line) {
            Ok(Value::Object(obj)) => {
                match obj.get("action").and_then(|v| v.as_str()) {
                    Some("status") => {
                        let status = obj
                            .get("status")
                            .and_then(|v| v.as_str())
                            .unwrap_or("error");
                        let msg = obj
                            .get("msg")
                            .and_then(|v| v.as_str())
                            .unwrap_or("")
                            .to_string();
                        let path = obj
                            .get("path")
                            .and_then(|v| v.as_str())
                            .unwrap_or(file)
                            .to_string();
                        last_status = Some(FileResult {
                            path,
                            status: match status {
                                "ok" => FileStatus::Ok,
                                "nochange" => FileStatus::Nochange,
                                "skip" => FileStatus::Skip,
                                _ => FileStatus::Error,
                            },
                            msg,
                        });
                    }
                    Some("report") => {
                        if let Some(msg) = obj.get("msg").and_then(|v| v.as_str()) {
                            report = Some(msg.to_string());
                        }
                    }
                    Some("update") => {
                        if let Some(msg) = obj.get("msg").and_then(|v| v.as_str()) {
                            update = Some(msg.to_string());
                        }
                    }
                    _ => {}
                }
            }
            _ => {}
        }
    }

    if let Some(status) = last_status {
        return (status, report, update);
    }

    let err_text = if stderr.is_empty() {
        stdout.to_string()
    } else {
        stderr.to_string()
    };
    let msg = format_error_message(file, &err_text, colors);
    (
        FileResult {
            path: file.to_string(),
            status: FileStatus::Error,
            msg,
        },
        report,
        update,
    )
}

pub fn format_error_message(file: &str, err: &str, colors: &Colors) -> String {
    let trimmed = err.trim_end();
    let file_colored = colors.red(file);
    if trimmed.is_empty() {
        return line_break(&file_colored);
    }
    format!("{file_colored}\n{trimmed}\n")
}

pub fn empty_stats() -> Stats {
    Stats {
        time_elapsed: 0.0,
        stats: Map::new(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn format_error_no_color() {
        let c = Colors::detect(&["--no-color".into()]);
        assert_eq!(format_error_message("a.js", "boom", &c), "a.js\nboom\n");
    }
}
"}

{"path":"/workspace/src/runner.rs","command":"create","file_text":"//! File discovery and transform runner matching `src/Runner.js`.

use crate::args::{
    option_bool, option_string, option_string_list, option_u32, DEFAULT_EXTENSIONS,
};
use crate::colors::Colors;
use crate::ignore::IgnoreSet;
use crate::package::find_package_root;
use crate::utils::{available_cpus, node_extname, path_resolve};
use crate::worker::{run_file, FileResult, FileStatus, Stats};
use serde_json::{json, Map, Value};
use std::collections::HashSet;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Instant;

pub struct RunCounters {
    pub ok: usize,
    pub nochange: usize,
    pub skip: usize,
    pub error: usize,
}

impl Default for RunCounters {
    fn default() -> Self {
        Self {
            ok: 0,
            nochange: 0,
            skip: 0,
            error: 0,
        }
    }
}

pub struct RunOutcome {
    pub stats: Stats,
    pub time_elapsed: f64,
    pub error: usize,
    pub ok: usize,
    pub nochange: usize,
    pub skip: usize,
}

pub fn run(
    transform_file: &str,
    paths: &[String],
    options: &Map<String, Value>,
    colors: &Colors,
) -> io::Result<RunOutcome> {
    run_with_io(transform_file, paths, options, colors, &mut io::stderr())
}

pub fn run_with_io<W: Write>(
    transform_file: &str,
    paths: &[String],
    options: &Map<String, Value>,
    colors: &Colors,
    err: &mut W,
) -> io::Result<RunOutcome> {
    let dry = option_bool(options, "dry");
    writeln!(
        err,
        "Processing {} file{}...",
        paths.len(),
        if paths.len() != 1 { "s" } else { "" }
    )?;
    if dry {
        writeln!(err, "Running in dry mode, no files will be written!")?;
    }

    let cpus = option_u32(options, "cpus").unwrap_or(available_cpus() as u32) as usize;
    let dry_flag = if dry { "yes" } else { "no" };
    writeln!(
        err,
        "Using {} worker{}...",
        cpus,
        if cpus != 1 { "s" } else { "" }
    )?;
    writeln!(err)?;
    let _ = dry_flag;

    let used_cpus = cpus.max(1).min(paths.len().max(1));
    let counters = Arc::new(Mutex::new(RunCounters::default()));
    let files: Arc<Mutex<Vec<String>>> = Arc::new(Mutex::new(paths.to_vec()));
    let next_index = Arc::new(AtomicUsize::new(0));
    let start = Instant::now();
    let transform = transform_file.to_string();
    let opts = options.clone();
    let colors_flag = colors.is_enabled();

    let mut handles = Vec::new();
    for _ in 0..used_cpus {
        let files = Arc::clone(&files);
        let next_index = Arc::clone(&next_index);
        let counters = Arc::clone(&counters);
        let transform = transform.clone();
        let opts = opts.clone();
        let handle = thread::spawn(move || {
            let colors = if colors_flag {
                Colors::detect(&["--color".into()])
            } else {
                Colors::detect(&["--no-color".into()])
            };
            loop {
                let idx = next_index.fetch_add(1, Ordering::SeqCst);
                let file = {
                    let list = files.lock().unwrap();
                    if idx >= list.len() {
                        break;
                    }
                    list[idx].clone()
                };
                let (result, report, update) = run_file(&file, &opts, &transform, &colors);
                emit_file_result(&result, &colors);
                if let Some(msg) = report {
                    emit_report(&msg, &colors);
                }
                if let Some(msg) = update {
                    let _ = eprint!("{msg}");
                }
                let mut c = counters.lock().unwrap();
                match result.status {
                    FileStatus::Ok => c.ok += 1,
                    FileStatus::Nochange => c.nochange += 1,
                    FileStatus::Skip => c.skip += 1,
                    FileStatus::Error => c.error += 1,
                }
            }
        });
        handles.push(handle);
    }

    for h in handles {
        let _ = h.join();
    }

    let elapsed = start.elapsed().as_secs_f64();
    let counts = counters.lock().unwrap();
    writeln!(err)?;
    writeln!(
        err,
        "All done. {}",
        colors.green(&format!("{:.3}s", elapsed))
    )?;
    writeln!(
        err,
        "Results: {} {} {} {}",
        counts.error,
        counts.ok,
        counts.nochange,
        counts.skip
    )?;

    Ok(RunOutcome {
        stats: Stats {
            time_elapsed: elapsed,
            stats: Map::new(),
        },
        time_elapsed: elapsed,
        error: counts.error,
        ok: counts.ok,
        nochange: counts.nochange,
        skip: counts.skip,
    })
}

pub fn emit_file_result(result: &FileResult, colors: &Colors) {
    match result.status {
        FileStatus::Ok => {
            eprint!("{} {}", colors.banner_ok(), result.path);
            if !result.msg.is_empty() {
                eprint!("\n{}", result.msg);
            } else {
                eprint!("\n");
            }
        }
        FileStatus::Nochange => {
            eprintln!("{} {}", colors.banner_nochange(), result.path);
        }
        FileStatus::Skip => {
            eprintln!("{} {}", colors.banner_skip(), result.path);
        }
        FileStatus::Error => {
            eprint!("{}", colors.banner_error());
            if !result.msg.is_empty() {
                eprint!(" {}", result.msg);
                if !result.msg.ends_with('\n') {
                    eprint!("\n");
                }
            } else {
                eprintln!(" {}", result.path);
            }
        }
    }
}

pub fn emit_report(msg: &str, colors: &Colors) {
    eprint!("{} {}", colors.banner_report(), msg);
    if !msg.ends_with('\n') {
        eprint!("\n");
    }
}

pub fn print_fatal(err: &str, colors: &Colors) {
    eprint!("{} {} {}", colors.banner_fatal(), colors.red("Error:"), err);
    if !err.ends_with('\n') {
        eprint!("\n");
    }
}

/// Recursively collect files matching `extensions`, applying ignore rules.
pub fn expand_file_paths(
    paths: &[String],
    extensions: &[String],
    ignore: &IgnoreSet,
) -> io::Result<Vec<String>> {
    let ext_set: HashSet<String> = extensions.iter().cloned().collect();
    let mut files = Vec::new();
    for p in paths {
        let resolved = path_resolve(p);
        visit_path(&resolved, &ext_set, ignore, &mut files)?;
    }
    Ok(files)
}

fn visit_path(
    path: &Path,
    ext_set: &HashSet<String>,
    ignore: &IgnoreSet,
    files: &mut Vec<String>,
) -> io::Result<()> {
    let display = path_to_string(path);
    if ignore.should_ignore(&display) {
        return Ok(());
    }

    let meta = match fs::metadata(path) {
        Ok(m) => m,
        Err(err) => {
            if err.kind() == io::ErrorKind::NotFound {
                return Ok(());
            }
            return Err(err);
        }
    };

    if meta.is_dir() {
        let entries = match fs::read_dir(path) {
            Ok(e) => e,
            Err(err) => {
                if err.kind() == io::ErrorKind::PermissionDenied {
                    return Ok(());
                }
                return Err(err);
            }
        };
        let mut kids: Vec<PathBuf> = entries
            .filter_map(|e| e.ok().map(|e| e.path()))
            .collect();
        kids.sort();
        for kid in kids {
            visit_path(&kid, ext_set, ignore, files)?;
        }
        return Ok(());
    }

    if meta.is_file() {
        let ext = node_extname(&display);
        let without_dot = ext.trim_start_matches('.');
        if ext_set.is_empty()
            || ext_set.contains(without_dot)
            || ext_set.contains(&ext)
            || ext_set.contains(&format!(".{without_dot}"))
        {
            files.push(display);
        }
    }
    Ok(())
}

fn path_to_string(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}

pub fn resolve_extensions(options: &Map<String, Value>) -> Vec<String> {
    let raw = option_string(options, "extensions").unwrap_or_else(|| DEFAULT_EXTENSIONS.to_string());
    raw.split(',')
        .map(|s| s.trim().trim_start_matches('.').to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

pub fn build_ignore_set(options: &Map<String, Value>) -> io::Result<IgnoreSet> {
    let mut set = IgnoreSet::new();
    set.add(option_string_list(options, "ignore"));
    set.add(option_string_list(options, "ignorePattern"));
    let configs = option_string_list(options, "ignoreConfig");
    if !configs.is_empty() {
        set.add_from_file(&configs[..])?;
    }
    if option_bool(options, "gitignore") {
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let gi = cwd.join(".gitignore");
        if gi.is_file() {
            set.add_from_file(gi.to_string_lossy().as_ref())?;
        }
    }
    Ok(set)
}

/// Prepare transform + file list, then run. Matches `bin/jscodeshift.js` after parse.
pub fn run_cli(paths: Vec<String>, mut options: Map<String, Value>, colors: &Colors) -> i32 {
    if option_bool(&options, "stdin") {
        return run_stdin(&options, colors);
    }

    if paths.is_empty() {
        print_fatal("Please provide at least one path or use --stdin to read from stdin", colors);
        return 1;
    }

    let transform = match option_string(&options, "transform") {
        Some(t) => t,
        None => {
            print_fatal("Missing required option: --transform", colors);
            return 1;
        }
    };

    let resolved_transform = match crate::args::resolve_transform_path(&transform) {
        Ok(p) => p,
        Err(err) => {
            print_fatal(&err.to_string(), colors);
            return 1;
        }
    };

    if !resolved_transform.starts_with("http://") && !resolved_transform.starts_with("https://") {
        let p = Path::new(&resolved_transform);
        if !p.is_file() {
            print_fatal(
                &format!("Transform file {resolved_transform} does not exist"),
                colors,
            );
            return 1;
        }
    }

    options.insert("transform".into(), json!(resolved_transform.clone()));

    let extensions = resolve_extensions(&options);
    let ignore = match build_ignore_set(&options) {
        Ok(s) => s,
        Err(err) => {
            print_fatal(&err.to_string(), colors);
            return 1;
        }
    };

    let files = match expand_file_paths(&paths, &extensions, &ignore) {
        Ok(f) => f,
        Err(err) => {
            print_fatal(&err.to_string(), colors);
            return 1;
        }
    };

    if files.is_empty() {
        eprintln!("No files selected, nothing to do.");
        return 0;
    }

    match run(&resolved_transform, &files, &options, colors) {
        Ok(outcome) => {
            if option_bool(&options, "fail-on-error") && outcome.error > 0 {
                1
            } else {
                0
            }
        }
        Err(err) => {
            print_fatal(&err.to_string(), colors);
            1
        }
    }
}

fn run_stdin(options: &Map<String, Value>, colors: &Colors) -> i32 {
    use std::io::Read;
    let mut source = String::new();
    if let Err(err) = io::stdin().read_to_string(&mut source) {
        print_fatal(&err.to_string(), colors);
        return 1;
    }

    let transform = match option_string(options, "transform") {
        Some(t) => t,
        None => {
            print_fatal("Missing required option: --transform", colors);
            return 1;
        }
    };
    let resolved = match crate::args::resolve_transform_path(&transform) {
        Ok(p) => p,
        Err(err) => {
            print_fatal(&err.to_string(), colors);
            return 1;
        }
    };

    // Write stdin to a temp file so the worker can treat it uniformly.
    let tmp = std::env::temp_dir().join(format!("jscodeshift-stdin-{}.js", process::id()));
    if let Err(err) = fs::write(&tmp, &source) {
        print_fatal(&err.to_string(), colors);
        return 1;
    }

    let mut opts = options.clone();
    opts.insert("print".into(), json!(true));
    opts.insert("dry".into(), json!(true));
    opts.insert("stdin".into(), json!(true));

    let path = tmp.to_string_lossy().into_owned();
    let (result, report, _) = run_file(&path, &opts, &resolved, colors);
    let _ = fs::remove_file(&tmp);
    if let Some(msg) = report {
        emit_report(&msg, colors);
    }
    match result.status {
        FileStatus::Error => {
            eprint!("{}", result.msg);
            if option_bool(options, "fail-on-error") {
                1
            } else {
                0
            }
        }
        _ => 0,
    }
}

pub fn default_package_root() -> PathBuf {
    find_package_root()
}

