{"path":"/workspace/src/main.rs","command":"create","file_text":"//! jscodeshift CLI.

use jscodeshift::args::{parse_cli, paths_from_positionals, ParseError};
use jscodeshift::colors::Colors;
use jscodeshift::runner::run_cli;
use std::env;
use std::io::{self, Write};
use std::process;

fn main() {
    let argv: Vec<String> = env::args().skip(1).collect();
    let colors = Colors::detect(&argv);

    match parse_cli(&argv) {
        Ok(parsed) => {
            let paths = paths_from_positionals(&parsed.positional_arguments);
            let code = run_cli(paths, parsed.options, &colors);
            process::exit(code);
        }
        Err(err) => {
            emit_parse_error(&err);
            process::exit(err.exit_code);
        }
    }
}

fn emit_parse_error(err: &ParseError) {
    let mut out: Box<dyn Write> = if err.exit_code == 0 {
        Box::new(io::stdout())
    } else {
        Box::new(io::stderr())
    };
    let _ = write!(out, "{}", err.message);
    if err.print_more_info {
        let _ = writeln!(out, "Run jscodeshift -h for more information");
    }
    if !err.message.ends_with('\n') && !err.print_more_info {
        let _ = writeln!(out);
    }
}
"}

