{"path":"/workspace/codebase/bridge/transform-host.js","command":"create","file_text":"/**
 * JavaScript compatibility bridge for transform execution.
 *
 * Rust owns the CLI, argument parser, file discovery, ignore rules, runner
 * orchestration, and package utilities. This host is the only remaining JS
 * needed to load transforms and apply recast / ast-types / Babel semantics
 * (collections, templates, node matching, parser adapters).
 */

'use strict';

const fs = require('fs');
const path = require('path');

const pkgRoot = path.resolve(__dirname, '..');

function installModuleAliases() {
  const Module = require('module');
  const orig = Module._resolveFilename;
  Module._resolveFilename = function (request, parent, isMain, options) {
    if (request === 'jscodeshift' || request === 'jscodeshift/src/core') {
      return path.join(pkgRoot, 'index.js');
    }
    if (request === 'jscodeshift/src/Collection') {
      return path.join(pkgRoot, 'src/Collection.js');
    }
    if (request.startsWith('jscodeshift/')) {
      return path.join(pkgRoot, request.slice('jscodeshift/'.length));
    }
    return orig.call(this, request, parent, isMain, options);
  };
}

installModuleAliases();

const getParser = require(path.join(pkgRoot, 'src/getParser'));
const jscodeshift = require(path.join(pkgRoot, 'src/core'));

function emit(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

function getJscodeshiftParser(parser, parserConfig) {
  if (typeof parser === 'string') {
    switch (parser) {
      case 'babel':
      case 'babylon':
      case 'flow':
      case 'ts':
      case 'tsx':
        return getParser(parser, parserConfig);
      default:
        try {
          return require(parser);
        } catch (err) {
          const req = require;
          const fromCwd = req.resolve(parser, {paths: [process.cwd()]});
          return req(fromCwd);
        }
    }
  } else if (typeof parser === 'object') {
    return parser;
  }
  return getParser(undefined, parserConfig);
}

function setupTrimmer(parser, parserConfig) {
  const {parse} = require('recast');
  const recastParser = getJscodeshiftParser(parser, parserConfig);
  const parsedEmpty = parse('', {parser: recastParser});
  const alignedForParser = parsedEmpty.program.body.length === 0
    && parsedEmpty.program.comments
    && parsedEmpty.program.comments.length === 1
    && parsedEmpty.program.comments[0].value === ' leading comment';

  return function trim(source) {
    if (alignedForParser) {
      return source.replace(/^\s+/, '');
    }
    return source;
  };
}

function createApi(file, stats, report, parser, parserConfig) {
  const jscodeshiftWithParser = parser
    ? jscodeshift.withParser(getJscodeshiftParser(parser, parserConfig))
    : jscodeshift;

  return {
    j: jscodeshiftWithParser,
    jscodeshift: jscodeshiftWithParser,
    stats: function (name, quantity) {
      quantity = typeof quantity !== 'number' ? 1 : quantity;
      if (!stats[name]) {
        stats[name] = 0;
      }
      stats[name] += quantity;
    },
    report: function (msg) {
      report.push(String(msg));
    },
  };
}

function prepareSource(source, parser, parserConfig) {
  const trim = setupTrimmer(parser, parserConfig);
  return trim(source);
}

function applyTransform(transform, source, file, options, api) {
  const out = transform(
    {
      path: file,
      source: source,
    },
    api,
    options
  );
  return out;
}

function writeResult(file, result, options) {
  if (result == null) {
    return 'skip';
  }
  if (typeof result !== 'string') {
    throw new Error(
      'Transformers must return a string or null / undefined. ' +
      'Got ' + typeof result + '.'
    );
  }

  const print = !!options.print;
  const dry = !!options.dry;
  const stdin = !!options.stdin;

  if (print) {
    process.stdout.write(result);
    if (!result.endsWith('\n')) {
      process.stdout.write('\n');
    }
  }

  if (!dry && !stdin) {
    fs.writeFileSync(file, result, 'utf8');
  }

  return 'ok';
}

function runOnce(payload) {
  const file = payload.file;
  const transformFile = payload.transformFile;
  const options = payload.options || {};
  const parser = options.parser;
  const parserConfig = options.parserConfig;

  let source;
  try {
    source = fs.readFileSync(file).toString();
  } catch (err) {
    emit({
      action: 'status',
      status: 'error',
      path: file,
      msg: file + ' ' + (err && err.stack ? err.stack : String(err)) + '\n',
    });
    return;
  }

  let transform;
  try {
    const abs = path.isAbsolute(transformFile)
      ? transformFile
      : path.resolve(process.cwd(), transformFile);
    delete require.cache[require.resolve(abs)];
    transform = require(abs);
    if (transform.__esModule && transform.default) {
      transform = transform.default;
    }
    if (typeof transform !== 'function' && transform && typeof transform.default === 'function') {
      transform = transform.default;
    }
    if (typeof transform !== 'function') {
      throw new Error(
        'Transform module must export a function, got ' + typeof transform
      );
    }
  } catch (err) {
    emit({
      action: 'status',
      status: 'error',
      path: file,
      msg: file + ' ' + (err && err.stack ? err.stack : String(err)) + '\n',
    });
    return;
  }

  const stats = {};
  const report = [];
  const api = createApi(file, stats, report, parser, parserConfig);

  let result;
  try {
    const prepared = prepareSource(source, parser, parserConfig);
    result = applyTransform(transform, prepared, file, options, api);
    if (result === undefined) {
      result = null;
    }
  } catch (err) {
    emit({
      action: 'status',
      status: 'error',
      path: file,
      msg: file + ' ' + (err && err.stack ? err.stack : String(err)) + '\n',
    });
    return;
  }

  if (result != null && typeof result !== 'string') {
    emit({
      action: 'status',
      status: 'error',
      path: file,
      msg: file + ' Transformers must return a string or null / undefined. Got ' + typeof result + '.\n',
    });
    return;
  }

  let status;
  try {
    if (result == null) {
      status = 'skip';
    } else if (result === source) {
      status = 'nochange';
      if (options.print) {
        process.stdout.write(result);
        if (!result.endsWith('\n')) {
          process.stdout.write('\n');
        }
      }
    } else {
      status = writeResult(file, result, options);
    }
  } catch (err) {
    emit({
      action: 'status',
      status: 'error',
      path: file,
      msg: file + ' ' + (err && err.stack ? err.stack : String(err)) + '\n',
    });
    return;
  }

  if (Object.keys(stats).length > 0) {
    emit({action: 'update', msg: JSON.stringify(stats)});
  }
  for (const msg of report) {
    emit({action: 'report', msg: String(msg)});
  }
  emit({action: 'status', status: status, path: file, msg: ''});
}

function main() {
  let buf = '';
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', (chunk) => {
    buf += chunk;
  });
  process.stdin.on('end', () => {
    const line = buf.trim();
    if (!line) {
      emit({
        action: 'status',
        status: 'error',
        path: '',
        msg: 'Missing worker payload\n',
      });
      return;
    }
    let payload;
    try {
      payload = JSON.parse(line);
    } catch (err) {
      emit({
        action: 'status',
        status: 'error',
        path: '',
        msg: String(err) + '\n',
      });
      return;
    }
    runOnce(payload);
  });
}

if (require.main === module) {
  main();
}

module.exports = {
  runOnce,
  createApi,
  getJscodeshiftParser,
};
"}

